pair O, A, B, C1, C2, G1, G2, M1, M2;
O = (0,0);
A = (-12,0);
B = (12,0);
C1 = (36/5,48/5);
C2 = (-96/17,-180/17);
G1 = O + 1/3 * C1;
G2 = O + 1/3 * C2;
M1 = (4,0);
M2 = (-4,0);

draw(Circle(O,12));
draw(Circle(O,4),red);

dot("$O$", O, (3/5,-4/5), linewidth(4.5));
dot("$A$", A, W, linewidth(4.5));
