label("$A$",A,S);
label("$B$",B,N);
label("$C$",C,W);
label("$D$",F,S);
label("$E$",G,W);

label("$3\sqrt{6}$",(1.5,1.5),S);
label("$3\sqrt{6}$",(-1.5,1.5),S);
label("$5\sqrt{2}$",(1,3.625),N);
label("$5\sqrt{2}$",(-1,3.625),N);
label("$I$",I,N);
label("$r$",(-0.25,1.5),E);
label("$r$",(0.5,2.125),S);
add(pathticks(A--F,1,0.5,0,2));
add(pathticks(F--B,1,0.5,0,2)); 
add(pathticks(A--G,1,0.5,0,2));
