D = intersectionpoints(Circle(A,15),Circle(C,20))[1];
fill(Circle(O,25/2),yellow);
fill(A--B--C--D--cycle,white);
dot("$A$",A,1.5*W,linewidth(4));
dot("$B$",B,1.5*dir(B),linewidth(4));
