draw((0,0) -- (1.5, 2.598), black); 
draw((0,0) -- (0, 2.598), black); 
draw((-3,0) -- (-2.598, 0), black); 
draw((3,0) -- (2.598, 0), black); 
dot((0,0)); 
dot((0,2.598)); 
dot((-1.5,2.598)); 
dot((1.5,2.598)); 
