B = (5.6, 4.2);
C = (5, 3.75);
D = (5, 0);
E = (0, 0);
F = (-0.6, 0.8);
fill(A--B--C--cycle, palered);
dot(A);
dot(B);
dot(C);
dot(D);
dot(E);
dot(F);
