\begin{align*}
\sqrt{x^2 - 2\sqrt{3}x + 12} &= \sqrt{13} - \sqrt{x^2 - \sqrt{3}x + 1}\\
x^2 - 2\sqrt{3}x + 12 &= x^2 - \sqrt{3}x + 1 + 13 - 2\sqrt{13(x^2 - \sqrt{3}x + 1)}\\
-\sqrt{3}x - 2 &= -2\sqrt{13(x^2 - \sqrt{3}x + 1)}\\
3x^2 + 4\sqrt{3}x + 4 &= 4\cdot13(x^2 - \sqrt{3}x + 1)\\
49x^2 - 56\sqrt{3}x + 48 &= 0\\
(7x-4\sqrt{3})^2 &= 0
\end{align*}
<imath>x = \frac{4\sqrt{3}}{7}</imath>
<imath>y = \frac{3\sqrt{3}}{7}</imath>
